#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

FUNCTION_APP="func-twopoint-website-api"
OWNER="tw0po1nt"
PRODUCTION_REPO="$OWNER/twopoint-website"
STAGING_REPO="$OWNER/twopoint-website-staging"
APP_NAME="twopoint site dispatch"
KEY_NAME="github-site-dispatch"
WEBHOOK_SECRET_NAME="github-site-dispatch-webhook-secret"

banner "Site dispatch: the GitHub App that rebuilds the site"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Azure and find the backend"
say "The wizard uses the Azure CLI for each change. It asks before each change."
if az account show >/dev/null 2>&1; then
  note "You are already signed in as $(az account show --query user.name -o tsv)."
else
  step "A browser window opens for the Azure sign-in."
  pause "Press Enter to start the sign-in."
  az login >/dev/null
fi
APP_RG=$(az functionapp list --query "[?name=='$FUNCTION_APP'].resourceGroup | [0]" -o tsv)
[[ -n "$APP_RG" ]] || { warn "Cannot find $FUNCTION_APP in this subscription."; exit 1; }
app_setting() {
  az functionapp config appsettings list -n "$FUNCTION_APP" -g "$APP_RG" --query "[?name=='$1'].value | [0]" -o tsv
}
VAULT_URI=$(app_setting "Azure__KeyVaultUri")
IDENTITY_CLIENT_ID=$(app_setting "Azure__ManagedIdentityClientId")
[[ -n "$VAULT_URI" ]] || { warn "$FUNCTION_APP has no setting Azure__KeyVaultUri."; exit 1; }
[[ -n "$IDENTITY_CLIENT_ID" ]] || { warn "$FUNCTION_APP has no setting Azure__ManagedIdentityClientId."; exit 1; }
VAULT_NAME=$(printf '%s' "$VAULT_URI" | sed -E 's#https://([^.]+)\..*#\1#')
IDENTITY_PRINCIPAL_ID=$(az identity list --query "[?clientId=='$IDENTITY_CLIENT_ID'].principalId | [0]" -o tsv)
[[ -n "$IDENTITY_PRINCIPAL_ID" ]] || { warn "Cannot find the managed identity $IDENTITY_CLIENT_ID."; exit 1; }
note "Function App: $FUNCTION_APP ($APP_RG)"
note "Key Vault: $VAULT_NAME"
note "Backend identity: $IDENTITY_CLIENT_ID"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Make the webhook secret"
say "A later version of the backend receives the workflow_run webhook of the app."
say "The backend checks each webhook with this secret, so the secret goes to Key Vault now."
if az keyvault secret show --vault-name "$VAULT_NAME" --name "$WEBHOOK_SECRET_NAME" >/dev/null 2>&1; then
  note "The secret $WEBHOOK_SECRET_NAME is already in $VAULT_NAME. The wizard uses it."
elif confirm "Make a random secret and write it to $VAULT_NAME as $WEBHOOK_SECRET_NAME?"; then
  az keyvault secret set --vault-name "$VAULT_NAME" --name "$WEBHOOK_SECRET_NAME" \
    --value "$(openssl rand -hex 32)" >/dev/null
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$WEBHOOK_SECRET_NAME" "$VAULT_NAME"
else
  SKIPPED+=("Write a random webhook secret to $VAULT_NAME as $WEBHOOK_SECRET_NAME")
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the GitHub App"
say "The app has only one permission: Actions, read and write, on the two site repos."
open_url "https://github.com/settings/apps/new"
step "GitHub App name: $APP_NAME"
step "Homepage URL: https://twopoint.dev"
step "Webhook: clear \"Active\". A later version of the backend sets the URL."
step "If the form shows \"Webhook secret\", paste the secret from the next line."
note "az keyvault secret show --vault-name $VAULT_NAME --name $WEBHOOK_SECRET_NAME --query value -o tsv"
step "Permissions > Repository permissions > Actions: Read and write. Change no other permission."
step "Where can this GitHub App be installed: Only on this account."
step "Click \"Create GitHub App\"."
step "On the page of the app, copy the Client ID (it starts with Iv)."
ask GITHUB_APP_CLIENT_ID "Paste the Client ID:"
[[ "$GITHUB_APP_CLIENT_ID" == Iv* ]] || warn "A Client ID usually starts with Iv. Make sure that you copied the Client ID."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Put the private key of the app in Key Vault"
say "Key Vault signs each app JWT, so the private key never leaves Key Vault."
step "On the page of the app, go to \"Private keys\" and click \"Generate a private key\"."
step "The browser downloads a .pem file."
ask PEM_FILE "Path of the .pem file:"
PEM_FILE="${PEM_FILE/#\~/$HOME}"
[[ -f "$PEM_FILE" ]] || { warn "No file at $PEM_FILE."; exit 1; }
if confirm "Import $PEM_FILE into $VAULT_NAME as the key $KEY_NAME?"; then
  az keyvault key import --vault-name "$VAULT_NAME" --name "$KEY_NAME" --pem-file "$PEM_FILE" --ops sign >/dev/null
  printf '  %s✓ imported%s %s → %s\n' "$GREEN" "$RESET" "$KEY_NAME" "$VAULT_NAME"
  if confirm "Delete $PEM_FILE? Key Vault now contains the only copy."; then
    rm -f "$PEM_FILE"
    printf '  %s✓ deleted%s %s\n' "$GREEN" "$RESET" "$PEM_FILE"
  else
    SKIPPED+=("Delete the private key file $PEM_FILE")
  fi
else
  SKIPPED+=("az keyvault key import --vault-name $VAULT_NAME --name $KEY_NAME --pem-file <the .pem file> --ops sign")
fi
KEY_URI="${VAULT_URI%/}/keys/$KEY_NAME"
say "The backend identity needs permission to sign with the key."
if [[ "$(az keyvault show --name "$VAULT_NAME" --query properties.enableRbacAuthorization -o tsv)" == "true" ]]; then
  KEY_SCOPE="$(az keyvault show --name "$VAULT_NAME" --query id -o tsv)/keys/$KEY_NAME"
  if confirm "Give the backend identity the role \"Key Vault Crypto User\" on $KEY_NAME?"; then
    az role assignment create --assignee-object-id "$IDENTITY_PRINCIPAL_ID" --assignee-principal-type ServicePrincipal \
      --role "Key Vault Crypto User" --scope "$KEY_SCOPE" >/dev/null
    printf '  %s✓ assigned%s Key Vault Crypto User on %s\n' "$GREEN" "$RESET" "$KEY_NAME"
  else
    SKIPPED+=("Assign Key Vault Crypto User on $KEY_SCOPE to $IDENTITY_PRINCIPAL_ID")
  fi
elif confirm "Give the backend identity the key permissions get and sign in the access policy of $VAULT_NAME?"; then
  az keyvault set-policy --name "$VAULT_NAME" --object-id "$IDENTITY_PRINCIPAL_ID" --key-permissions get sign >/dev/null
  printf '  %s✓ set%s the key permissions get and sign\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Give $IDENTITY_PRINCIPAL_ID the key permissions get and sign on $VAULT_NAME")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Install the app on the two site repos"
step "On the page of the app, click \"Install App\", then \"Install\" next to $OWNER."
step "Choose \"Only select repositories\" and select these two repos:"
note "$PRODUCTION_REPO"
note "$STAGING_REPO"
step "Click \"Install\"."
pause "Press Enter after the install."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Give the settings to the backend"
say "The backend reads the repos and the app from these settings of $FUNCTION_APP:"
note "Deploy__ProductionRepo=$PRODUCTION_REPO"
note "Deploy__StagingRepo=$STAGING_REPO"
note "Deploy__GitHubApp__ClientId=$GITHUB_APP_CLIENT_ID"
note "Deploy__GitHubApp__SigningKeyUri=$KEY_URI"
if confirm "Write the four settings to $FUNCTION_APP? The Function App restarts."; then
  az functionapp config appsettings set -n "$FUNCTION_APP" -g "$APP_RG" --settings \
    "Deploy__ProductionRepo=$PRODUCTION_REPO" \
    "Deploy__StagingRepo=$STAGING_REPO" \
    "Deploy__GitHubApp__ClientId=$GITHUB_APP_CLIENT_ID" \
    "Deploy__GitHubApp__SigningKeyUri=$KEY_URI" >/dev/null
  printf '  %s✓ wrote%s the settings to %s\n' "$GREEN" "$RESET" "$FUNCTION_APP"
else
  SKIPPED+=("Write the four Deploy__ settings to $FUNCTION_APP")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Check a rebuild"
say "Do this check after the backend with \"Rebuild site\" is deployed."
open_url "https://admin.twopoint.dev/"
step "On the dashboard, click \"Rebuild site\"."
step "The card shows the number of the production run."
open_url "https://github.com/$PRODUCTION_REPO/actions/workflows/site.yml"
open_url "https://github.com/$STAGING_REPO/actions/workflows/site.yml"
step "Each repo shows a new workflow_dispatch run of site.yml."
pause

finish
}

run_wizard "$@"; exit
